function navigate(hash){if(location.hash===hash)render();else location.hash=hash;}
function parseRoute(){const [path,query='']=(location.hash.slice(1)||'home').split('?');const bits=path.split('/').map(decodeURIComponent);return {home:bits[0]==='home',api:names[bits[0]]?bits[0]:'features',page:bits[1]||'overview',id:bits[2],sub:bits[3],item:bits[4],params:new URLSearchParams(query)};}
